use serde_json::Value;
use std::collections::BinaryHeap;
use std::cmp::Ordering;

pub fn solve(input: Value) -> Value {
    let mut heap = BinaryHeap::from(input.iter().flat_map(|(k, v)| vec![(*k, *v)]).collect::<Vec<_>>());
    heap.sort_by(|a, b| match a.1.cmp(&b.1) {
        Ordering::Equal => a.0.cmp(&b.0),
        Ordering::Less => Ordering::Less,
        Ordering::Greater => Ordering::Greater,
    });
    let mut result = vec![];
    while let Some(item) = heap.pop() {
        result.push(item);
    }
    Value::Array(result)
}
```

This code uses the BinaryHeap data structure from the standard collections library in Rust to sort the input array of [key, value] pairs. The sorting is done in ascending order based on the values. The sorted pairs are then pushed into a new array and returned as the result.
